internal class ReferenceFilterCatalogPanelCache {
    private var catalog: ReferenceClassCatalog? = null

    fun update(
        next: ReferenceClassCatalog?,
        on_identity_changed: () -> Unit,
    ): ReferenceClassCatalog? {
        if (next !== catalog) {
            catalog = next
            on_identity_changed()
        }
        return catalog
    }
