// Owns street-map tile loading and drawing. Satellite transitions and overlays live in SatelliteMapTileRenderer.
internal class StreetMapTileRenderer(
    private val context: Context,
    private val paint: Paint,
    private val text_paint: Paint,
    private val sp: (Float) -> Float,
    private val with_alpha: (Int, Int) -> Int,
    private val report_failure: (MapTileFailureKind) -> Unit,
    private val request_redraw: () -> Unit,
    private val map_tile_disk_cache: MapTileDiskCache,
) {
    private val tile_cache = LinkedHashMap<String, Bitmap>(MAX_MEMORY_TILES, 0.75f, true)
    private val label_tile_cache = LinkedHashMap<String, Bitmap>(MAX_LABEL_MEMORY_TILES, 0.75f, true)
    private val requested_tiles_lock = Any()
    private val requested_tiles = mutableSetOf<String>()
    private val requested_tile_generations = mutableMapOf<String, Long>()
    private val tile_request_admission_lock = Any()
    private val active_tile_connections_lock = Any()
    private val active_tile_connections = mutableMapOf<String, HttpURLConnection>()
    @Volatile
    private var closed = false
    @Volatile
    private var published_tile_request_generation = 0L
    private val worker_id = AtomicInteger()
    private val tile_request_generation = AtomicLong()
    private val tile_task_sequence = AtomicLong()
    private val tile_executor = ThreadPoolExecutor(
        TILE_NETWORK_THREADS,
        TILE_NETWORK_THREADS,
        TILE_WORKER_KEEP_ALIVE_MS,
        TimeUnit.MILLISECONDS,
        PriorityBlockingQueue()
    ) { runnable ->
        Thread(runnable, "flightalert-street-tile-${worker_id.incrementAndGet()}").apply {
            isDaemon = true
        }
    }.apply {
        allowCoreThreadTimeOut(true)
    }
    private val bitmap_paint = Paint(Paint.FILTER_BITMAP_FLAG or Paint.DITHER_FLAG)
    private val tile_destination = RectF()
    private val label_boost_destination = RectF()
    private val child_destination = RectF()
    private val parent_source = Rect()
    private val tile_decode_options = ThreadLocal.withInitial {
        BitmapFactory.Options().apply {
            inPreferredConfig = Bitmap.Config.ARGB_8888
        }
    }
    fun draw_tiles(
        canvas: Canvas,
        viewport: Viewport,
        state: MapTileRenderState,
        style: MapTileRenderStyle
    ): MapTileAvailability {
        paint.style = Paint.Style.FILL
        paint.color = style.map_empty
        canvas.drawRect(0f, 0f, viewport.width, viewport.height, paint)

        val request_generation = tile_request_generation.incrementAndGet()
        val base_cache_key = TileSource.STREET.cache_key(labels_enabled = state.map_labels_enabled)
        val base_stats = draw_tile_grid(
            canvas = canvas,
            viewport = viewport,
            state = state,
            style = style,
            cache_key = base_cache_key,
            tile_url = { z, x, y ->
                TileSource.STREET.tile_url(z, x, y, labels_enabled = state.map_labels_enabled)
            },
            label_scale = 1f,
            draw_unavailable_if_missing = true,
            request_generation = request_generation
        )
        if (
            state.map_labels_enabled &&
            state.map_label_transition_alpha > MIN_LABEL_TRANSITION_ALPHA &&
            base_stats.requested == 0 &&
            state.map_label_text_scale > 1.01f
        ) {
            draw_tile_grid(
                canvas = canvas,
                viewport = viewport,
                state = state,
                style = style,
                cache_key = STREET_LABEL_CACHE_KEY,
                tile_url = { z, x, y -> TileSource.STREET.street_label_tile_url(z, x, y) },
                label_scale = state.map_label_text_scale,
                label_alpha = state.map_label_transition_alpha,
                draw_unavailable_if_missing = false,
                defer_until_exact_tiles_loaded = true,
                request_generation = request_generation
            )
        }
        publish_desired_tile_generation(request_generation)
        return MapTileAvailability(
            loaded = base_stats.loaded,
            requested = base_stats.requested,
        )
    }

    private fun draw_tile_grid(
        canvas: Canvas,
        viewport: Viewport,
        state: MapTileRenderState,
        style: MapTileRenderStyle,
        cache_key: String,
        tile_url: (Int, Int, Int) -> String,
        label_scale: Float,
        label_alpha: Float = 1f,
        draw_unavailable_if_missing: Boolean,
        defer_until_exact_tiles_loaded: Boolean = false,
        request_generation: Long
    ): TileLayerDrawStats {
        val left_world = viewport.center_x - viewport.width / 2.0
        val top_world = viewport.center_y - viewport.height / 2.0
        val tile_zoom = viewport.zoom.toInt().coerceIn(MIN_ZOOM, TileSource.STREET.max_native_zoom)
        val tile_to_viewport_scale = 2.0.pow(viewport.zoom - tile_zoom)
        val tile_world_scale = 1.0 / tile_to_viewport_scale
        val first_tile_x = floor(left_world * tile_world_scale / TILE_SIZE).toInt()
        val first_tile_y = floor(top_world * tile_world_scale / TILE_SIZE).toInt()
        val last_tile_x =
            floor((left_world + viewport.width) * tile_world_scale / TILE_SIZE).toInt()
        val last_tile_y =
            floor((top_world + viewport.height) * tile_world_scale / TILE_SIZE).toInt()
        val max_tile = 1 shl tile_zoom
        val tile_size_on_screen = (TILE_SIZE * tile_to_viewport_scale).toFloat()
        var visible = 0
        var loaded = 0
        var requested = 0
        var fallback_drawn = 0

        if (defer_until_exact_tiles_loaded) {
            var exact_visible = 0
            var exact_loaded = 0
            var exact_requested = 0
            for (ty in first_tile_y..last_tile_y) {
                if (ty !in 0 until max_tile) continue
                for (tx_raw in first_tile_x..last_tile_x) {
                    val tx = ((tx_raw % max_tile) + max_tile) % max_tile
                    val key = "$cache_key/$tile_zoom/$tx/$ty"
                    exact_visible++
                    if (memory_tile_bitmap(key) != null) {
                        exact_loaded++
                    } else {
                        exact_requested++
                        request_tile(
                            tile_zoom,
                            tx,
                            ty,
                            key,
                            state,
                            cache_key,
                            tile_url,
                            request_generation = request_generation,
                            request_priority = TILE_REQUEST_PRIORITY_EXACT
                        )
                    }
                }
            }
            if (exact_requested > 0) {
                return TileLayerDrawStats(
                    exact_visible,
                    exact_loaded,
                    exact_requested,
                    fallback_drawn = 0,
                    fading = false
                )
            }
        }

        for (ty in first_tile_y..last_tile_y) {
            if (ty !in 0 until max_tile) continue
            for (tx_raw in first_tile_x..last_tile_x) {
                val tx = ((tx_raw % max_tile) + max_tile) % max_tile
                val key = "$cache_key/$tile_zoom/$tx/$ty"
                val screen_x = (tx_raw * TILE_SIZE * tile_to_viewport_scale - left_world).toFloat()
                val screen_y = (ty * TILE_SIZE * tile_to_viewport_scale - top_world).toFloat()
                tile_destination.set(
                    screen_x,
                    screen_y,
                    screen_x + tile_size_on_screen,
                    screen_y + tile_size_on_screen
                )
                val bitmap = memory_tile_bitmap(key)
                visible++
                if (bitmap != null) {
                    loaded++
                    draw_tile_bitmap(canvas, bitmap, tile_destination, label_scale, label_alpha)
                } else {
                    requested++
                    request_parent_tiles(
                        tile_zoom,
                        tx,
                        ty,
                        state,
                        cache_key,
                        tile_url,
                        request_generation = request_generation
                    )
                    request_tile(
                        tile_zoom,
                        tx,
                        ty,
                        key,
                        state,
                        cache_key,
                        tile_url,
                        request_generation = request_generation,
                        request_priority = TILE_REQUEST_PRIORITY_EXACT
                    )
                    val drew_fallback = draw_unavailable_if_missing &&
                            (draw_parent_tile_fallback(
                                canvas,
                                tile_zoom,
                                tx,
                                ty,
                                cache_key,
                                tile_destination
                            ) || draw_child_tile_fallback(
                                canvas,
                                tile_zoom,
                                tx,
                                ty,
                                cache_key,
                                tile_destination
                            ))
                    if (drew_fallback) fallback_drawn++
                    if (!drew_fallback && draw_unavailable_if_missing) {
                        draw_unavailable_tile(
                            canvas,
                            screen_x,
                            screen_y,
                            tile_size_on_screen,
                            style
                        )
                    }
                }
            }
        }
        return TileLayerDrawStats(visible, loaded, requested, fallback_drawn, fading = false)
    }

    fun clear() {
        synchronized(tile_cache) {
            tile_cache.clear()
        }
        synchronized(label_tile_cache) {
            label_tile_cache.clear()
        }
        synchronized(requested_tiles_lock) {
            requested_tiles.clear()
            requested_tile_generations.clear()
        }
    }

    fun reset_transitions() {
        synchronized(requested_tiles_lock) {
            requested_tiles.clear()
            requested_tile_generations.clear()
        }
    }

    fun shutdown() {
        synchronized(tile_cache) { closed = true }
        synchronized(label_tile_cache) { closed = true }
        synchronized(active_tile_connections_lock) {
            active_tile_connections.values.forEach(HttpURLConnection::disconnect)
            active_tile_connections.clear()
        }
        tile_executor.shutdownNow().forEach { task ->
            (task as? TileRequestTask)?.discard()
        }
        clear()
    }

    private fun request_parent_tiles(
        z: Int,
        x: Int,
        y: Int,
        state: MapTileRenderState,
        cache_key: String,
        tile_url: (Int, Int, Int) -> String,
        request_generation: Long
    ) {
        if (z <= MIN_ZOOM) return
        val max_depth = (z - MIN_ZOOM).coerceAtMost(STREET_PARENT_REQUEST_DEPTH)
        for (depth in max_depth downTo 1) {
            val scale = 1 shl depth
            val parent_z = z - depth
            val parent_x = x / scale
            val parent_y = y / scale
            val parent_key = "$cache_key/$parent_z/$parent_x/$parent_y"
            if (memory_tile_bitmap(parent_key) == null) {
                request_tile(
                    parent_z,
                    parent_x,
                    parent_y,
                    parent_key,
                    state,
                    cache_key,
                    tile_url,
                    request_generation = request_generation,
                    request_priority = TILE_REQUEST_PRIORITY_PARENT_BASE - depth
                )
            }
        }
    }

    private fun request_tile(
        z: Int,
        x: Int,
        y: Int,
        key: String,
        state: MapTileRenderState,
        cache_key: String,
        tile_url: (Int, Int, Int) -> String,
        request_generation: Long,
        request_priority: Int
    ) {
        if (closed || memory_tile_bitmap(key) != null) return
        synchronized(requested_tiles_lock) {
            requested_tile_generations[key] = request_generation
            if (!requested_tiles.add(key)) return
        }
        submit_tile_request(
            TileRequestTask(
                key = key,
                generation = request_generation,
                priority = request_priority,
                sequence = tile_task_sequence.incrementAndGet(),
                action = {
                    load_tile(z, x, y, key, state, cache_key, tile_url)
                }
            )
        )
    }

    private fun submit_tile_request(task: TileRequestTask) {
        var discarded: TileRequestTask? = null
        var submitted = false
        synchronized(tile_request_admission_lock) {
            if (!closed && !tile_executor.isShutdown) {
                val queue = tile_executor.queue
                if (queue.size >= MAX_PENDING_TILE_REQUESTS) {
                    var worst: TileRequestTask? = null
                    for (queued in queue) {
                        val candidate = queued as? TileRequestTask ?: continue
                        if (worst == null || candidate > worst) worst = candidate
                    }
                    if (worst != null &&
                        task < worst &&
                        queue.remove(worst)
                    ) {
                        discarded = worst
                    }
                }
                if (queue.size < MAX_PENDING_TILE_REQUESTS) {
                    try {
                        tile_executor.execute(task)
                        submitted = true
                    } catch (_: RejectedExecutionException) {
                        // Cleanup below releases rejected work.
                    }
                }
            }
        }
        discarded?.discard()
        if (!submitted) task.discard()
    }

    private fun release_requested_tile(key: String) {
        synchronized(requested_tiles_lock) {
            requested_tiles.remove(key)
            requested_tile_generations.remove(key)
        }
    }

    private fun tile_request_is_current(key: String): Boolean {
        if (closed) return false
        val published_generation = published_tile_request_generation
        return synchronized(requested_tiles_lock) {
            (requested_tile_generations[key] ?: Long.MIN_VALUE) >= published_generation
        }
    }

    private fun publish_desired_tile_generation(generation: Long) {
        published_tile_request_generation = generation
        val discarded = ArrayList<TileRequestTask>()
        synchronized(tile_request_admission_lock) {
            val iterator = tile_executor.queue.iterator()
            while (iterator.hasNext()) {
                val task = iterator.next() as? TileRequestTask ?: continue
                if (!task.is_desired_for(generation)) {
                    iterator.remove()
                    discarded += task
                }
            }
        }
        discarded.forEach(TileRequestTask::discard)
        val stale_connections = synchronized(active_tile_connections_lock) {
            active_tile_connections
                .filterKeys { key -> !tile_request_is_current(key) }
                .values
                .toList()
        }
        stale_connections.forEach(HttpURLConnection::disconnect)
    }

    private fun load_tile(
        z: Int,
        x: Int,
        y: Int,
        key: String,
        state: MapTileRenderState,
        cache_key: String,
        tile_url: (Int, Int, Int) -> String,
    ) {
        var connection: HttpURLConnection? = null
        var redrew_when_loaded = false
        var skipped_loaded_request = false
        try {
            if (!tile_request_is_current(key) || memory_tile_bitmap(key) != null) {
                skipped_loaded_request = true
                return
            }
            val file = tile_file(z, x, y, cache_key)
            val bitmap = map_tile_disk_cache.read_if_fresh(
                file = file,
                max_age_ms = MAP_TILE_CACHE_MAX_AGE_MS,
            ) { cached ->
                if (!tile_request_is_current(key)) {
                    null
                } else {
                    BitmapFactory.decodeFile(cached.absolutePath, decode_options())
                }
            }
            if (bitmap != null) {
                if (!tile_request_is_current(key) || !put_tile_in_memory(key, bitmap)) {
                    bitmap.recycle()
                    skipped_loaded_request = true
                }
                return
            }
            if (!tile_request_is_current(key)) {
                skipped_loaded_request = true
                return
            }
            val url = https_url(tile_url(z, x, y))
                ?: run {
                    if (!closed) report_failure(MapTileFailureKind.PROVIDER_UNAVAILABLE)
                    return
                }
            connection = (url.openConnection() as HttpURLConnection).apply {
                connectTimeout = 8000
                readTimeout = 10000
                requestMethod = "GET"
                setRequestProperty("User-Agent", state.user_agent)
            }
            synchronized(active_tile_connections_lock) {
                if (!tile_request_is_current(key)) {
                    skipped_loaded_request = true
                    return
                }
                active_tile_connections[key] = connection
            }
            if (connection.responseCode == HttpURLConnection.HTTP_OK) {
                if (!tile_request_is_current(key)) {
                    skipped_loaded_request = true
                    return
                }
                val bytes = connection.inputStream.use { it.readBytes() }
                if (!tile_request_is_current(key)) {
                    skipped_loaded_request = true
                    return
                }
                val downloaded = BitmapFactory.decodeByteArray(
                    bytes,
                    0,
                    bytes.size,
                    decode_options()
                )
                if (downloaded != null) {
                    if (tile_request_is_current(key) &&
                        put_tile_in_memory(key, downloaded)
                    ) {
                        redrew_when_loaded = true
                        request_redraw()
                        write_tile_file_async(file, bytes)
                    } else {
                        downloaded.recycle()
                        skipped_loaded_request = true
                    }
                }
            } else if (tile_request_is_current(key)) {
                connection.errorStream?.close()
                report_failure(MapTileFailureKind.PROVIDER_UNAVAILABLE)
            }
        } catch (_: Exception) {
            if (tile_request_is_current(key)) report_failure(MapTileFailureKind.NETWORK_UNAVAILABLE)
        } finally {
            synchronized(active_tile_connections_lock) {
                if (active_tile_connections[key] === connection) {
                    active_tile_connections.remove(key)
                }
            }
            connection?.disconnect()
            release_requested_tile(key)
            if (!closed && !redrew_when_loaded && !skipped_loaded_request) request_redraw()
        }
    }

    private fun write_tile_file_async(file: File, bytes: ByteArray) {
        if (!closed) map_tile_disk_cache.write_async(file, bytes)
    }

    private fun memory_tile_bitmap(key: String): Bitmap? {
        val cache = memory_cache_for_key(key)
        return synchronized(cache) { cache[key] }
    }

    private fun put_tile_in_memory(key: String, bitmap: Bitmap): Boolean {
        if (closed) return false
        val cache = memory_cache_for_key(key)
        synchronized(cache) {
            if (closed) return false
            put_tile_in_memory_locked(cache, key, bitmap)
            return true
        }
    }

    private fun put_tile_in_memory_locked(
        cache: LinkedHashMap<String, Bitmap>,
        key: String,
        bitmap: Bitmap
    ) {
        cache[key] = bitmap
        while (cache.size > max_memory_tiles_for_key(key)) {
            val first_key = cache.keys.firstOrNull() ?: break
            cache.remove(first_key)
        }
    }

    private fun memory_cache_for_key(key: String): LinkedHashMap<String, Bitmap> {
        return if (key.startsWith("$STREET_LABEL_CACHE_KEY/")) label_tile_cache else tile_cache
    }

    private fun max_memory_tiles_for_key(key: String): Int {
        return if (key.startsWith("$STREET_LABEL_CACHE_KEY/")) {
            MAX_LABEL_MEMORY_TILES
        } else {
            MAX_MEMORY_TILES
        }
    }

    private fun draw_parent_tile_fallback(
        canvas: Canvas,
        z: Int,
        x: Int,
        y: Int,
        cache_key: String,
        destination: RectF
    ): Boolean {
        if (z <= MIN_ZOOM) return false
        var fallback_z = z - 1
        while (fallback_z >= MIN_ZOOM) {
            val delta = z - fallback_z
            val scale = 1 shl delta
            val parent_x = x / scale
            val parent_y = y / scale
            val parent_key = "$cache_key/$fallback_z/$parent_x/$parent_y"
            val bitmap = memory_tile_bitmap(parent_key)
            if (bitmap != null) {
                val src_width = (bitmap.width / scale).coerceAtLeast(1)
                val src_height = (bitmap.height / scale).coerceAtLeast(1)
                val child_x = x % scale
                val child_y = y % scale
                val left = (child_x * src_width).coerceIn(0, bitmap.width - 1)
                val top = (child_y * src_height).coerceIn(0, bitmap.height - 1)
                parent_source.set(
                    left,
                    top,
                    (left + src_width).coerceAtMost(bitmap.width),
                    (top + src_height).coerceAtMost(bitmap.height)
                )
                bitmap_paint.alpha = 255
                canvas.drawBitmap(bitmap, parent_source, destination, bitmap_paint)
                return true
            }
            fallback_z -= 1
        }
        return false
    }

    private fun draw_child_tile_fallback(
        canvas: Canvas,
        z: Int,
        x: Int,
        y: Int,
        cache_key: String,
        destination: RectF
    ): Boolean {
        val max_depth =
            (TileSource.STREET.max_native_zoom - z).coerceAtMost(STREET_CHILD_FALLBACK_DEPTH)
        if (max_depth <= 0) return false
        for (depth in 1..max_depth) {
            val scale = 1 shl depth
            val child_z = z + depth
            var all_children_available = true
            for (child_y_offset in 0 until scale) {
                if (!all_children_available) break
                for (child_x_offset in 0 until scale) {
                    val child_x = x * scale + child_x_offset
                    val child_y = y * scale + child_y_offset
                    val child_key = "$cache_key/$child_z/$child_x/$child_y"
                    if (memory_tile_bitmap(child_key) == null) {
                        all_children_available = false
                        break
                    }
                }
            }
            if (!all_children_available) continue

            val child_width = destination.width() / scale
            val child_height = destination.height() / scale
            for (child_y_offset in 0 until scale) {
                for (child_x_offset in 0 until scale) {
                    val child_x = x * scale + child_x_offset
                    val child_y = y * scale + child_y_offset
                    val child_key = "$cache_key/$child_z/$child_x/$child_y"
                    val bitmap = memory_tile_bitmap(child_key) ?: return false
                    child_destination.set(
                        destination.left + child_x_offset * child_width,
                        destination.top + child_y_offset * child_height,
                        destination.left + (child_x_offset + 1) * child_width,
                        destination.top + (child_y_offset + 1) * child_height
                    )
                    bitmap_paint.alpha = 255
                    canvas.drawBitmap(bitmap, null, child_destination, bitmap_paint)
                }
            }
            return true
        }
        return false
    }

    private fun draw_tile_bitmap(
        canvas: Canvas,
        bitmap: Bitmap,
        destination: RectF,
        label_scale: Float = 1f,
        label_alpha: Float = 1f
    ) {
        val safe_alpha = label_alpha.coerceIn(0f, 1f)
        val scale = label_scale.coerceIn(MAP_LABEL_TEXT_SCALE_MIN, MAP_LABEL_TEXT_SCALE_MAX)
        if (scale <= 1.01f) {
            bitmap_paint.alpha = (255f * safe_alpha).toInt().coerceIn(0, 255)
            canvas.drawBitmap(bitmap, null, destination, bitmap_paint)
            bitmap_paint.alpha = 255
            return
        }
        val progress = ((scale - 1f) / (MAP_LABEL_TEXT_SCALE_MAX - 1f)).coerceIn(0f, 1f)
        bitmap_paint.alpha = (LABEL_BOOST_CENTER_ALPHA * progress * safe_alpha)
            .toInt()
            .coerceIn(0, 255)
        canvas.drawBitmap(bitmap, null, destination, bitmap_paint)
        val offset = LABEL_BOOST_MAX_OFFSET_PX * progress
        if (offset >= 0.35f) {
            bitmap_paint.alpha = (LABEL_BOOST_OFFSET_ALPHA * progress * safe_alpha)
                .toInt()
                .coerceIn(0, 255)
            draw_label_boost_offset(canvas, bitmap, destination, -offset, 0f)
            draw_label_boost_offset(canvas, bitmap, destination, offset, 0f)
            draw_label_boost_offset(canvas, bitmap, destination, 0f, -offset)
            draw_label_boost_offset(canvas, bitmap, destination, 0f, offset)
        }
        bitmap_paint.alpha = 255
    }

    private fun draw_label_boost_offset(
        canvas: Canvas,
        bitmap: Bitmap,
        destination: RectF,
        dx: Float,
        dy: Float
    ) {
        label_boost_destination.set(
            destination.left + dx,
            destination.top + dy,
            destination.right + dx,
            destination.bottom + dy
        )
        canvas.drawBitmap(bitmap, null, label_boost_destination, bitmap_paint)
    }

    private fun draw_unavailable_tile(
        canvas: Canvas,
        x: Float,
        y: Float,
        size: Float,
        style: MapTileRenderStyle
    ) {
        draw_unavailable_map_tile(
            canvas,
            paint,
            text_paint,
            x,
            y,
            size,
            style.panel_alt,
            with_alpha(style.text, 170),
            sp(10f)
        )
    }

    private fun tile_file(z: Int, x: Int, y: Int, cache_key: String): File {
        return map_tile_cache_file(context, cache_key, z, x, y)
    }

    private fun decode_options(): BitmapFactory.Options {
        val options = tile_decode_options.get() ?: BitmapFactory.Options().apply {
            inPreferredConfig = Bitmap.Config.ARGB_8888
            tile_decode_options.set(this)
        }
        options.inJustDecodeBounds = false
        options.inBitmap = null
        options.inSampleSize = 1
        return options
    }

    private fun https_url(value: String): URL? = throwable_safe_https_url(value)

    private inner class TileRequestTask(
        private val key: String,
        private val generation: Long,
        private val priority: Int,
        private val sequence: Long,
        private val action: () -> Unit
    ) : Runnable, Comparable<Runnable> {
        override fun run() = action()

        fun discard() = release_requested_tile(key)

        fun is_desired_for(published_generation: Long): Boolean =
            synchronized(requested_tiles_lock) {
                (requested_tile_generations[key] ?: Long.MIN_VALUE) >= published_generation
            }

        override fun compareTo(other: Runnable): Int {
            val task = other as? TileRequestTask ?: return -1
            if (generation != task.generation) return task.generation.compareTo(generation)
            if (priority != task.priority) return priority.compareTo(task.priority)
            return sequence.compareTo(task.sequence)
        }
    }

    private companion object {
        const val TILE_SIZE = 256
        const val MIN_ZOOM = 3
        const val MAX_MEMORY_TILES = 320
        const val MAX_LABEL_MEMORY_TILES = 192
        const val TILE_NETWORK_THREADS = 6
        const val MAX_PENDING_TILE_REQUESTS = 192
        const val TILE_WORKER_KEEP_ALIVE_MS = 15_000L
        const val STREET_PARENT_REQUEST_DEPTH = 3
        const val STREET_CHILD_FALLBACK_DEPTH = 2
        const val TILE_REQUEST_PRIORITY_PARENT_BASE = 3
        const val TILE_REQUEST_PRIORITY_EXACT = 4
        const val STREET_LABEL_CACHE_KEY = "carto_voyager_only_labels"
        const val MAP_LABEL_TEXT_SCALE_MIN = 1f
        const val MAP_LABEL_TEXT_SCALE_MAX = 1.75f
        const val MIN_LABEL_TRANSITION_ALPHA = 0.01f
        const val LABEL_BOOST_CENTER_ALPHA = 135
        const val LABEL_BOOST_OFFSET_ALPHA = 70
        const val LABEL_BOOST_MAX_OFFSET_PX = 1.4f
    }
}

// endregion

// region source: java/com/flightalert/RenderingPrimitives.kt

internal fun smooth_step(edge0: Float, edge1: Float, value: Float): Float {
    val t = ((value - edge0) / (edge1 - edge0)).coerceIn(0f, 1f)
    return t * t * (3f - 2f * t)
}

internal fun safe_smooth_step(edge0: Float, edge1: Float, value: Float): Float {
    if (edge0 == edge1) return if (value >= edge1) 1f else 0f
    return smooth_step(edge0, edge1, value)
}

internal fun lerp(start: Float, end: Float, progress: Float): Float {
    return start + (end - start) * progress.coerceIn(0f, 1f)
}

internal fun mix_color(start: Int, end: Int, progress: Float): Int {
    val t = progress.coerceIn(0f, 1f)
    return Color.rgb(
        lerp(Color.red(start).toFloat(), Color.red(end).toFloat(), t).roundToInt().coerceIn(0, 255),
        lerp(Color.green(start).toFloat(), Color.green(end).toFloat(), t).roundToInt()
            .coerceIn(0, 255),
        lerp(Color.blue(start).toFloat(), Color.blue(end).toFloat(), t).roundToInt()
            .coerceIn(0, 255)
    )
}

internal fun with_alpha(color: Int, alpha: Int): Int {
    return Color.argb(
        alpha.coerceIn(0, 255),
        Color.red(color),
        Color.green(color),
        Color.blue(color)
    )
}

// Cache/state builders intentionally share geometric growth. The renderer keeps its
// separate exact-size growth path because that allocation policy is a hot-path choice.
internal fun ensure_point_capacity(points: FloatArray, required: Int): FloatArray {
    if (points.size >= required) return points
    var next_size = max(128, points.size * 2)
    while (next_size < required) next_size *= 2
    return points.copyOf(next_size)
}

internal fun recycle_bitmap_pair(first: Bitmap, second: Bitmap) {
    first.recycle()
    second.recycle()
}

// endregion

// region source: java/com/flightalert/sources/AircraftFeedClient.kt

class AircraftFeedClient(private val user_agent: String) {

    // Fetch the visible area first, then merge an exact search result if the user is filtering for one aircraft.
    fun fetch_aircraft(
        bounds: FeedBounds,
        own_lat: Double,
        own_lon: Double,
        exact_search: String? = null
    ): FeedResult {
        val viewport_result = fetch_viewport_aircraft(bounds, own_lat, own_lon)
        val search_result = fetch_airplanes_live_exact_search(exact_search, own_lat, own_lon)
        return merge_viewport_and_search(viewport_result, search_result)
    }

    // Prefer Airplanes.Live coverage, then fall back to OpenSky only when the primary source is not usable.
    private fun fetch_viewport_aircraft(
        bounds: FeedBounds,
        own_lat: Double,
        own_lon: Double
    ): FeedResult {
        if (bounds.min_lon <= bounds.max_lon) {
            return fetch_non_wrapping_viewport_aircraft(bounds, own_lat, own_lon)
        }
        val west = fetch_non_wrapping_viewport_aircraft(
            bounds.copy(max_lon = 180.0),
            own_lat,
            own_lon
        )
        val east = fetch_non_wrapping_viewport_aircraft(
            bounds.copy(min_lon = -180.0),
            own_lat,
            own_lon
        )
        return merge_wrapped_viewport_results(west, east)
    }

    private fun fetch_non_wrapping_viewport_aircraft(
        bounds: FeedBounds,
        own_lat: Double,
        own_lon: Double
    ): FeedResult {
        val now = System.currentTimeMillis()
        val airplanes_result = if (now >= airplanes_live_retry_after_ms) {
            fetch_airplanes_live(bounds, own_lat, own_lon)
        } else {
            FeedResult(
                FeedStatus.RATE_LIMITED,
                FeedSource.AIRPLANES_LIVE,
                http_code = HTTP_TOO_MANY_REQUESTS
            )
        }
        if (airplanes_result.status == FeedStatus.OK) {
            return airplanes_result
        }

        val open_sky_result =
            if (now >= open_sky_retry_after_ms) fetch_open_sky(bounds, own_lat, own_lon) else null
        if (open_sky_result?.status == FeedStatus.OK) return open_sky_result

        return open_sky_result ?: airplanes_result
    }

    private fun merge_wrapped_viewport_results(
        west: FeedResult,
        east: FeedResult
    ): FeedResult {
        if (west.status != FeedStatus.OK && east.status != FeedStatus.OK) {
            return if (east.status == FeedStatus.RATE_LIMITED) east else west
        }
        if (west.status != FeedStatus.OK || east.status != FeedStatus.OK) {
            val available = if (west.status == FeedStatus.OK) west else east
            return available.copy(
                query_count = west.query_count + east.query_count,
                partial_coverage = true
            )
        }
        val merged = linkedMapOf<String, FeedAircraft>()
        west.aircraft.forEach { item -> merged[item.feed_key()] = item }
        east.aircraft.forEach { item ->
            val key = item.feed_key()
            merged[key] = newer_aircraft(merged[key], item)
        }
        return FeedResult(
            status = FeedStatus.OK,
            source = merged_source(west.source, east.source),
            aircraft = merged.values.sortedBy { it.distance_m },
            epoch_sec = max_epoch(west.epoch_sec, east.epoch_sec),
            query_count = west.query_count + east.query_count,
            partial_coverage = west.partial_coverage || east.partial_coverage
        )
    }

    private fun merge_viewport_and_search(viewport: FeedResult, search: FeedResult?): FeedResult {
        if (search == null) return viewport
        if (search.status != FeedStatus.OK) return viewport
        if (viewport.status != FeedStatus.OK) return search
        if (search.aircraft.isEmpty()) return viewport.copy(query_count = viewport.query_count + search.query_count)
        return merge_complete_coverage_with_detail(viewport, search)
    }

    // Merge detail rows into complete coverage by aircraft key, keeping the newest real report for each aircraft.
    private fun merge_complete_coverage_with_detail(
        complete: FeedResult,
        detail: FeedResult
    ): FeedResult {
        val merged = linkedMapOf<String, FeedAircraft>()
        complete.aircraft.forEach { item ->
            merged[item.feed_key()] = item
        }
        detail.aircraft.forEach { item ->
            val key = item.feed_key()
            merged[key] = newer_aircraft(merged[key], item)
        }
        return FeedResult(
            status = FeedStatus.OK,
            source = merged_source(complete.source, detail.source),
            aircraft = merged.values.sortedBy { it.distance_m },
            epoch_sec = max_epoch(complete.epoch_sec, detail.epoch_sec),
            query_count = complete.query_count + detail.query_count,
            partial_coverage = false
        )
    }

    private fun fetch_open_sky(bounds: FeedBounds, own_lat: Double, own_lon: Double): FeedResult {
        var connection: HttpURLConnection? = null
        return try {
            val url = URL(
                String.format(
                    Locale.US,
                    "https://opensky-network.org/api/states/all?lamin=%.5f&lomin=%.5f&lamax=%.5f&lomax=%.5f&extended=1",
                    bounds.min_lat,
                    bounds.min_lon,
                    bounds.max_lat,
                    bounds.max_lon
                )
            )
            connection = open_connection(url)
            when (val code = connection.responseCode) {
                HttpURLConnection.HTTP_OK -> {
                    val body = connection.inputStream.bufferedReader().use { it.readText() }
                    val json = JSONObject(body)
                    FeedResult(
                        status = FeedStatus.OK,
                        source = FeedSource.OPENSKY,
                        aircraft = parse_open_sky_aircraft(json, own_lat, own_lon),
                        epoch_sec = json.feed_json_finite_double_or_null("time")
                    )
                }

                HTTP_TOO_MANY_REQUESTS -> {
                    val retry_seconds =
                        connection.getHeaderField("X-Rate-Limit-Retry-After-Seconds")
                            ?.toLongOrNull()
                    open_sky_retry_after_ms = System.currentTimeMillis() + ((retry_seconds
                        ?: DEFAULT_OPENSKY_BACKOFF_SECONDS) * 1000L)
                    connection.errorStream?.close()
                    FeedResult(FeedStatus.RATE_LIMITED, FeedSource.OPENSKY, http_code = code)
                }

                else -> {
                    connection.errorStream?.close()
                    FeedResult(FeedStatus.UNAVAILABLE, FeedSource.OPENSKY, http_code = code)
                }
            }
        } catch (_: Exception) {
            FeedResult(FeedStatus.UNAVAILABLE, FeedSource.OPENSKY)
        } finally {
            connection?.disconnect()
        }
    }

    // Split large bounds into real point queries so Airplanes.Live can cover the visible area honestly.
    private fun fetch_airplanes_live(
        bounds: FeedBounds,
        own_lat: Double,
        own_lon: Double
    ): FeedResult {
        val plan = airplanes_live_query_plan(bounds)
        val merged = linkedMapOf<String, FeedAircraft>()
        var latest_epoch_sec: Double? = null
        var saw_ok = false
        var saw_rate_limit = false
        var last_http_code: Int? = null
        val query_results = fetch_airplanes_live_points(plan.queries, own_lat, own_lon)
        val timed_out = query_results.size < plan.queries.size

        for (result in query_results) {
            latest_epoch_sec = max_epoch(latest_epoch_sec, result.epoch_sec)
            last_http_code = result.http_code ?: last_http_code
            when (result.status) {
                FeedStatus.OK -> {
                    saw_ok = true
                    result.aircraft.forEach { item ->
                        val key = item.feed_key()
                        merged[key] = newer_aircraft(merged[key], item)
                    }
                }

                FeedStatus.RATE_LIMITED -> {
                    saw_rate_limit = true
                    last_http_code = result.http_code ?: HTTP_TOO_MANY_REQUESTS
                }

                FeedStatus.UNAVAILABLE -> Unit
            }
        }

        return when {
            saw_ok -> FeedResult(
                status = FeedStatus.OK,
                source = FeedSource.AIRPLANES_LIVE,
                aircraft = merged.values.sortedBy { it.distance_m },
                epoch_sec = latest_epoch_sec,
                query_count = plan.queries.size,
                partial_coverage = plan.partial_coverage || timed_out
            )

            saw_rate_limit -> FeedResult(
                status = FeedStatus.RATE_LIMITED,
                source = FeedSource.AIRPLANES_LIVE,
                http_code = last_http_code,
                query_count = plan.queries.size,
                partial_coverage = plan.partial_coverage
            )

            else -> FeedResult(
                status = FeedStatus.UNAVAILABLE,
                source = FeedSource.AIRPLANES_LIVE,
                http_code = last_http_code,
                query_count = plan.queries.size,
                partial_coverage = plan.partial_coverage || timed_out
            )
        }
    }

    private fun fetch_airplanes_live_points(
        queries: List<AirplanesLiveQuery>,
        own_lat: Double,
        own_lon: Double
    ): List<FeedResult> {
        return queries.map { query -> fetch_airplanes_live_point(query, own_lat, own_lon) }
    }

    private fun fetch_airplanes_live_point(
        query: AirplanesLiveQuery,
        own_lat: Double,
        own_lon: Double
    ): FeedResult {
        val path = String.format(
            Locale.US,
            "point/%.5f/%.5f/%.0f",
            query.center_lat,
            query.center_lon,
            query.radius_nm
        )
        return fetch_airplanes_live_path(path, own_lat, own_lon)
    }

    private fun fetch_airplanes_live_exact_search(
        search: String?,
        own_lat: Double,
        own_lon: Double
    ): FeedResult? {
        val path = airplanes_live_search_path(search) ?: return null
        if (System.currentTimeMillis() < airplanes_live_retry_after_ms) {
            return FeedResult(
                FeedStatus.RATE_LIMITED,
                FeedSource.AIRPLANES_LIVE,
                http_code = HTTP_TOO_MANY_REQUESTS
            )
        }
        return fetch_airplanes_live_path(path, own_lat, own_lon)
    }

    // All Airplanes.Live REST calls pass through the shared rate limiter and report failure instead of inventing data.
    private fun fetch_airplanes_live_path(
        path: String,
        own_lat: Double,
        own_lon: Double
    ): FeedResult {
        var connection: HttpURLConnection? = null
        return try {
            AirplanesLiveHttp.wait_for_rest_api_slot()
            val url = URL("${AirplanesLiveHttp.API_BASE_URL}/$path")
            connection = open_connection(url)
            val code = connection.responseCode
            if (code == HttpURLConnection.HTTP_OK) {
                val body = connection.inputStream.bufferedReader().use { it.readText() }
                val json = JSONObject(body)
                FeedResult(
                    status = FeedStatus.OK,
                    source = FeedSource.AIRPLANES_LIVE,
                    aircraft = parse_airplanes_live_aircraft(json, own_lat, own_lon),
                    epoch_sec = json.feed_json_finite_double_or_null("now")
                        ?.let { normalize_epoch_seconds(it) },
                    query_count = 1
                )
            } else {
                if (code == HTTP_TOO_MANY_REQUESTS) {
                    val retry_seconds = connection.getHeaderField("Retry-After")?.toLongOrNull()
                        ?: DEFAULT_AIRPLANES_LIVE_BACKOFF_SECONDS
                    AirplanesLiveHttp.back_off_rest_api(retry_seconds)
                    airplanes_live_retry_after_ms =
                        System.currentTimeMillis() + retry_seconds * 1000L
                }
                connection.errorStream?.close()
                FeedResult(
                    status = if (code == HTTP_TOO_MANY_REQUESTS) FeedStatus.RATE_LIMITED else FeedStatus.UNAVAILABLE,
                    source = FeedSource.AIRPLANES_LIVE,
                    http_code = code,
                    query_count = 1
                )
            }
        } catch (_: Exception) {
            FeedResult(FeedStatus.UNAVAILABLE, FeedSource.AIRPLANES_LIVE, query_count = 1)
        } finally {
            connection?.disconnect()
        }
    }

    private fun airplanes_live_search_path(search: String?): String? {
        val raw = search?.trim().orEmpty()
        if (raw.length < 2) return null
        val compact = raw.replace("\\s+".toRegex(), "").take(MAX_EXACT_SEARCH_CHARS)
        if (!EXACT_SEARCH_ALLOWED.matches(compact)) return null
        val upper = compact.uppercase(Locale.US)
        return when {
            MODE_S_HEX.matches(upper) -> "hex/${upper.lowercase(Locale.US)}"
            looks_like_registration_search(upper) -> "reg/${URLEncoder.encode(upper, "UTF-8")}"
            CALLSIGN_SEARCH.matches(upper) -> "callsign/${URLEncoder.encode(upper, "UTF-8")}"
            else -> null
        }
    }

    private fun looks_like_registration_search(upper: String): Boolean {
        return upper.startsWith("N") || upper.contains("-")
    }

    // Build a bounded grid of point queries; mark partial coverage when the viewport is too large for one pass.
    private fun airplanes_live_query_plan(bounds: FeedBounds): AirplanesLiveQueryPlan {
        val normalized = bounds.normalized()
        val center_lat = (normalized.min_lat + normalized.max_lat) / 2.0
        val center_lon = (normalized.min_lon + normalized.max_lon) / 2.0
        val width_m =
            feed_distance_meters(center_lat, normalized.min_lon, center_lat, normalized.max_lon)
        val height_m =
            feed_distance_meters(normalized.min_lat, center_lon, normalized.max_lat, center_lon)
        val target_cell_span_m =
            MAX_AIRPLANES_RADIUS_NM * METERS_PER_NAUTICAL_MILE * AIRPLANES_GRID_CELL_RADIUS_FACTOR
        var columns = ceil(width_m / target_cell_span_m).toInt().coerceAtLeast(1)
        var rows = ceil(height_m / target_cell_span_m).toInt().coerceAtLeast(1)
        val needed_rows = rows
        val needed_columns = columns
        while (rows * columns > MAX_AIRPLANES_LIVE_QUERIES) {
            if (columns >= rows && columns > 1) columns-- else if (rows > 1) rows-- else break
        }

        val queries = mutableListOf<AirplanesLiveQuery>()
        for (row in 0 until rows) {
            val min_lat = lerp(normalized.min_lat, normalized.max_lat, row.toDouble() / rows)
            val max_lat = lerp(normalized.min_lat, normalized.max_lat, (row + 1.0) / rows)
            for (column in 0 until columns) {
                val min_lon =
                    lerp(normalized.min_lon, normalized.max_lon, column.toDouble() / columns)
                val max_lon = lerp(normalized.min_lon, normalized.max_lon, (column + 1.0) / columns)
                val cell = FeedBounds(min_lat, min_lon, max_lat, max_lon)
                val cell_center_lat = (min_lat + max_lat) / 2.0
                val cell_center_lon = (min_lon + max_lon) / 2.0
                queries += AirplanesLiveQuery(
                    center_lat = cell_center_lat,
                    center_lon = cell_center_lon,
                    radius_nm = radius_nm_for(cell, cell_center_lat, cell_center_lon)
                        .times(AIRPLANES_QUERY_RADIUS_PADDING)
                        .coerceIn(MIN_AIRPLANES_RADIUS_NM, MAX_AIRPLANES_RADIUS_NM)
                )
            }
        }

        return AirplanesLiveQueryPlan(
            queries = queries.ifEmpty {
                listOf(AirplanesLiveQuery(center_lat, center_lon, MIN_AIRPLANES_RADIUS_NM))
            },
            partial_coverage = rows < needed_rows || columns < needed_columns
        )
    }

    private fun open_connection(url: URL): HttpURLConnection {
        require(
            url.protocol.equals(
                "https",
                ignoreCase = true
            )
        ) { "Only HTTPS aircraft feeds are allowed" }
        return (url.openConnection() as HttpURLConnection).apply {
            connectTimeout = 4000
            readTimeout = 6000
            requestMethod = "GET"
            if (url.host.equals("api.airplanes.live", ignoreCase = true)) {
                AirplanesLiveHttp.apply_browser_headers(this, user_agent)
            } else {
                setRequestProperty("User-Agent", user_agent)
                setRequestProperty("Accept", "application/json")
            }
        }
    }

    // Translate OpenSky arrays into the app feed model while leaving missing fields null.
    private fun parse_open_sky_aircraft(
        json: JSONObject,
        own_lat: Double,
        own_lon: Double
    ): List<FeedAircraft> {
        val rows = json.optJSONArray("states") ?: JSONArray()
        val parsed = mutableListOf<FeedAircraft>()
        for (index in 0 until rows.length()) {
            val row = rows.optJSONArray(index) ?: continue
            val lon = row.json_number_or_null(5) ?: continue
            val lat = row.json_number_or_null(6) ?: continue
            val icao24 = row.optString(0).trim()
            val callsign = row.optString(1).trim().ifEmpty { icao24.ifEmpty { "Unknown" } }
            val altitude_m = row.json_number_or_null(7) ?: row.json_number_or_null(13)
            val velocity_ms = row.json_number_or_null(9)
            val vertical_rate_ms = row.json_number_or_null(11)
            parsed += FeedAircraft(
                icao24 = icao24,
                callsign = callsign,
                registration = null,
                type_code = null,
                db_flags = null,
                lat = lat,
                lon = lon,
                on_ground = row.feed_json_array_boolean_or_null(8),
                altitude_m = altitude_m,
                velocity_ms = velocity_ms,
                track_deg = row.json_number_or_null(10),
                vertical_rate_ms = vertical_rate_ms,
                category = row.json_int_or_null(17),
                position_time_sec = row.json_number_or_null(3),
                last_contact_sec = row.json_number_or_null(4),
                distance_m = feed_distance_meters(own_lat, own_lon, lat, lon),
                telemetry = AircraftTelemetry(
                    source_type = "OpenSky",
                    baro_altitude_m = altitude_m,
                    ground_speed_ms = velocity_ms,
                    baro_rate_ms = vertical_rate_ms
                ).takeIf { it.has_values }
            )
        }
        return parsed.sortedBy { it.distance_m }
    }

    // Translate Airplanes.Live objects into the app feed model without filling missing source fields.
    private fun parse_airplanes_live_aircraft(
        json: JSONObject,
        own_lat: Double,
        own_lon: Double
    ): List<FeedAircraft> {
        val now_sec =
            json.feed_json_finite_double_or_null("now")?.let { normalize_epoch_seconds(it) }
                ?: (System.currentTimeMillis() / 1000.0)
        val rows = json.optJSONArray("aircraft") ?: json.optJSONArray("ac") ?: JSONArray()
        val parsed = mutableListOf<FeedAircraft>()
        for (index in 0 until rows.length()) {
            val item = rows.optJSONObject(index) ?: continue
            val lat =
                item.feed_json_finite_double_or_null("lat") ?: item.optJSONObject("lastPosition")
                    ?.feed_json_finite_double_or_null("lat") ?: continue
            val lon =
                item.feed_json_finite_double_or_null("lon") ?: item.optJSONObject("lastPosition")
                    ?.feed_json_finite_double_or_null("lon") ?: continue
            val icao24 = item.optString("hex").trim().lowercase(Locale.US)
            val callsign = item.optString("flight").trim()
                .ifEmpty { item.optString("r").trim().ifEmpty { icao24.ifEmpty { "Unknown" } } }
            val type_code = item.optString("t").trim().ifEmpty { null }
            val altitude_feet =
                item.json_number_or_null("alt_baro") ?: item.json_number_or_null("alt_geom")
            val seen_position_sec = item.feed_json_finite_double_or_null("seen_pos")
            val seen_message_sec = item.feed_json_finite_double_or_null("seen")
            val last_position_time = seen_position_sec?.let { now_sec - it }
            val last_contact_time = seen_message_sec?.let { now_sec - it } ?: last_position_time
            val vertical_rate_ms = (item.feed_json_finite_double_or_null("baro_rate")
                ?: item.feed_json_finite_double_or_null("geom_rate"))
                ?.let { feed_feet_per_minute_to_meters_per_second(it) }
            val telemetry = item.airplanes_live_telemetry()
            parsed += FeedAircraft(
                icao24 = icao24,
                callsign = callsign,
                registration = item.optString("r").trim().ifEmpty { null },
                type_code = type_code,
                db_flags = item.feed_json_int_or_null("dbFlags"),
                lat = lat,
                lon = lon,
                on_ground = item.optString("alt_baro") == "ground",
                altitude_m = altitude_feet?.let { it / FEET_PER_METER },
                velocity_ms = item.feed_json_finite_double_or_null("gs")
                    ?.let { feed_knots_to_meters_per_second(it) },
                track_deg = item.feed_json_finite_double_or_null("track"),
                vertical_rate_ms = vertical_rate_ms,
                category = adsb_emitter_category(item.optString("category")),
                position_time_sec = last_position_time,
                last_contact_sec = last_contact_time,
                distance_m = feed_distance_meters(own_lat, own_lon, lat, lon),
                telemetry = telemetry
            )
        }
        return parsed.sortedBy { it.distance_m }
    }

    private fun JSONObject.airplanes_live_telemetry(): AircraftTelemetry? {
        val telemetry = AircraftTelemetry(
            source_type = feed_json_string_or_null("type")
                ?: feed_json_string_or_null("source_type"),
            squawk = feed_json_string_or_null("squawk"),
            baro_altitude_m = json_number_or_null("alt_baro")?.let { it / FEET_PER_METER },
            geom_altitude_m = json_number_or_null("alt_geom")?.let { it / FEET_PER_METER },
            ground_speed_ms = feed_json_finite_double_or_null("gs")?.let {
                feed_knots_to_meters_per_second(
                    it
                )
            },
            true_speed_ms = feed_json_finite_double_or_null("tas")?.let {
                feed_knots_to_meters_per_second(
                    it
                )
            },
            indicated_speed_ms = feed_json_finite_double_or_null("ias")?.let {
                feed_knots_to_meters_per_second(
                    it
                )
            },
            mach = feed_json_finite_double_or_null("mach"),
            baro_rate_ms = feed_json_finite_double_or_null("baro_rate")?.let {
                feed_feet_per_minute_to_meters_per_second(
                    it
                )
            },
            geom_rate_ms = feed_json_finite_double_or_null("geom_rate")?.let {
                feed_feet_per_minute_to_meters_per_second(
                    it
                )
            },
            selected_altitude_m = (json_number_or_null("nav_altitude_mcp")
                ?: json_number_or_null("nav_altitude_fms"))?.let { it / FEET_PER_METER },
            selected_heading_deg = feed_json_finite_double_or_null("nav_heading"),
            wind_speed_ms = feed_json_finite_double_or_null("ws")?.let {
                feed_knots_to_meters_per_second(
                    it
                )
            },
            wind_direction_deg = feed_json_finite_double_or_null("wd"),
            tat_c = feed_json_finite_double_or_null("tat"),
            oat_c = feed_json_finite_double_or_null("oat"),
            qnh_hpa = feed_json_finite_double_or_null("nav_qnh"),
            true_heading_deg = feed_json_finite_double_or_null("true_heading"),
            magnetic_heading_deg = feed_json_finite_double_or_null("mag_heading"),
            magnetic_declination_deg = feed_json_finite_double_or_null("mag_declination"),
            track_rate_deg_per_sec = feed_json_finite_double_or_null("track_rate"),
            roll_deg = feed_json_finite_double_or_null("roll"),
            nav_modes = feed_json_string_list("nav_modes"),
            adsb_version = feed_json_number_as_string_or_null("version")?.let { "v$it" },
            nac_p = feed_json_int_or_null("nac_p"),
            nac_v = feed_json_int_or_null("nac_v"),
            sil = feed_json_int_or_null("sil"),
            sil_type = feed_json_string_or_null("sil_type"),
            nic_baro = feed_json_number_as_string_or_null("nic_baro"),
            rc_m = feed_json_finite_double_or_null("rc"),
            rssi = feed_json_finite_double_or_null("rssi"),
            message_rate = feed_json_message_rate_or_null(),
            receiver_count_label = feed_json_receiver_count_label(),
            category_label = feed_json_string_or_null("category")
        )
        return telemetry.takeIf { it.has_values }
    }

    private fun radius_nm_for(bounds: FeedBounds, center_lat: Double, center_lon: Double): Double {
        val corners = listOf(
            bounds.min_lat to bounds.min_lon,
            bounds.min_lat to bounds.max_lon,
            bounds.max_lat to bounds.min_lon,
            bounds.max_lat to bounds.max_lon
        )
        return corners.maxOf { (lat, lon) ->
            feed_distance_meters(
                center_lat,
                center_lon,
                lat,
                lon
            )
        } / METERS_PER_NAUTICAL_MILE
    }

    private fun normalize_epoch_seconds(value: Double): Double {
        return if (value > 10_000_000_000.0) value / 1000.0 else value
    }

    // When two feeds report the same aircraft, keep the one with the newest contact time.
    private fun newer_aircraft(existing: FeedAircraft?, incoming: FeedAircraft): FeedAircraft {
        if (existing == null) return incoming
        val existing_time = existing.last_contact_sec ?: existing.position_time_sec ?: 0.0
        val incoming_time = incoming.last_contact_sec ?: incoming.position_time_sec ?: 0.0
        return if (incoming_time >= existing_time) incoming else existing
    }

    private fun lerp(start: Double, end: Double, amount: Double): Double {
        return start + (end - start) * amount
    }

    private fun merged_source(first: FeedSource, second: FeedSource): FeedSource {
        return if (first == second) first else FeedSource.COMBINED
    }

    companion object {
        private const val HTTP_TOO_MANY_REQUESTS =
            FlightAlertAppSettings.AircraftFeed.HTTP_TOO_MANY_REQUESTS
        private const val DEFAULT_OPENSKY_BACKOFF_SECONDS =
            FlightAlertAppSettings.AircraftFeed.DEFAULT_OPENSKY_BACKOFF_SECONDS
        private const val DEFAULT_AIRPLANES_LIVE_BACKOFF_SECONDS =
            FlightAlertAppSettings.AircraftFeed.DEFAULT_AIRPLANES_LIVE_BACKOFF_SECONDS
        private const val MIN_AIRPLANES_RADIUS_NM =
            FlightAlertAppSettings.AircraftFeed.MIN_AIRPLANES_RADIUS_NM
        private const val MAX_AIRPLANES_RADIUS_NM =
            FlightAlertAppSettings.AircraftFeed.MAX_AIRPLANES_RADIUS_NM
        private const val MAX_AIRPLANES_LIVE_QUERIES =
            FlightAlertAppSettings.AircraftFeed.MAX_AIRPLANES_LIVE_QUERIES
        private const val AIRPLANES_GRID_CELL_RADIUS_FACTOR =
            FlightAlertAppSettings.AircraftFeed.AIRPLANES_GRID_CELL_RADIUS_FACTOR
        private const val AIRPLANES_QUERY_RADIUS_PADDING =
            FlightAlertAppSettings.AircraftFeed.AIRPLANES_QUERY_RADIUS_PADDING
        private const val METERS_PER_NAUTICAL_MILE = 1852.0
        private const val FEET_PER_METER = 3.28084
        private const val MAX_EXACT_SEARCH_CHARS =
            FlightAlertAppSettings.AircraftFeed.MAX_EXACT_SEARCH_CHARS
        private val EXACT_SEARCH_ALLOWED = Regex("^[A-Za-z0-9-]+$")
        private val MODE_S_HEX = Regex("^[0-9A-F]{6}$")
        private val CALLSIGN_SEARCH = Regex("^[A-Z0-9]{2,12}$")

        @Volatile
        private var open_sky_retry_after_ms = 0L

        @Volatile
        private var airplanes_live_retry_after_ms = 0L
    }
}

internal object AirplanesLiveHttp {
    const val GLOBE_BASE_URL = "https://globe.airplanes.live"
    const val API_BASE_URL = "https://api.airplanes.live/v2"
    const val STATIC_DB_BASE_URL = "https://static.airplanes.live/db"

    private const val BROWSER_USER_AGENT =
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 " +
                "(KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36"
    private const val REST_MIN_INTERVAL_MS = 1100L
    private val rest_lock = Any()

    @Volatile
    private var next_rest_request_at_ms = 0L

    fun apply_browser_headers(
        connection: HttpURLConnection,
        app_user_agent: String,
        referer: String? = GLOBE_BASE_URL,
        accept: String = "application/json,text/plain,*/*"
    ) {
        connection.setRequestProperty("User-Agent", browser_user_agent(app_user_agent))
        connection.setRequestProperty("Accept", accept)
        connection.setRequestProperty("Accept-Language", "en-US,en;q=0.9")
        connection.setRequestProperty("Cache-Control", "no-cache")
        referer?.let { connection.setRequestProperty("Referer", it) }
    }

    fun wait_for_rest_api_slot() {
        synchronized(rest_lock) {
            val now = System.currentTimeMillis()
            val wait_ms = next_rest_request_at_ms - now
            if (wait_ms > 0L) {
                try {
                    Thread.sleep(wait_ms)
                } catch (_: InterruptedException) {
                    Thread.currentThread().interrupt()
                }
            }
            next_rest_request_at_ms = System.currentTimeMillis() + REST_MIN_INTERVAL_MS
        }
    }

    fun back_off_rest_api(retry_after_seconds: Long?) {
        val retry_ms = (retry_after_seconds ?: 2L).coerceAtLeast(1L) * 1000L
        synchronized(rest_lock) {
            next_rest_request_at_ms =
                maxOf(next_rest_request_at_ms, System.currentTimeMillis() + retry_ms)
        }
    }

    fun browser_user_agent(app_user_agent: String): String {
        val trimmed = app_user_agent.trim()
        if (trimmed.contains("Mozilla/", ignoreCase = true)) return trimmed
        return if (trimmed.isEmpty()) BROWSER_USER_AGENT else "$BROWSER_USER_AGENT $trimmed"
    }
}

