    fun draw_filters_panel(
        canvas: Canvas,
        w: Float,
        h: Float,
        style: FlightMapPanelStyle,
        state: FiltersPanelState
    ) {
        paint.style = Paint.Style.FILL
        val rect = chrome.layout.settings_panel_bounds(w, h)
        chrome.draw_panel_surface(
            canvas,
            rect,
            style.visual_theme.colors.panel_alt,
            style.visual_theme.style.modal_panel_alpha
        )
        draw_reference_panel_header(canvas, rect, style, state)

        when (state.reference_panel_plan.content) {
            ReferenceFiltersPanelContent.TRAFFIC_SLOT -> {
                draw_traffic_filters_panel(canvas, rect, style, state)
            }
            ReferenceFiltersPanelContent.MAP_UNAVAILABLE,
            ReferenceFiltersPanelContent.MAP_FILTERS -> {
                draw_reference_map_filters(canvas, rect, style, state)
            }
        }
    }

    private fun draw_reference_panel_header(
        canvas: Canvas,
        panel: RectF,
        style: FlightMapPanelStyle,
        state: FiltersPanelState,
    ) {
        val plan = state.reference_panel_plan
        plan.title?.let { title ->
            draw_reference_text_plan(
                canvas,
                panel,
                title,
                style,
                style.visual_theme.colors.text,
            )
        }
        plan.controls.filter { it.kind != ReferenceControlKind.SWITCH }.forEach { control ->
            val focused = control.actionId == state.reference_focused_action_id
            val selected = control.selected == true || focused
            chrome.draw_control_surface(
                canvas,
                control.bounds.to_pixel_rect(panel, state.pixels_per_dp),
                style.visual_theme.colors.button_fill,
                if (selected) {
                    style.visual_theme.colors.accent_blue
                } else {
                    style.visual_theme.colors.button_stroke
                },
                selected,
            )
            control.labelText?.let { label ->
                draw_reference_text_plan(
                    canvas,
                    panel,
                    label,
                    style,
                    style.visual_theme.colors.text,
                    centerHorizontally = true,
                )
            }
        }
    }

    private fun draw_traffic_filters_panel(
        canvas: Canvas,
        panel: RectF,
        style: FlightMapPanelStyle,
        state: FiltersPanelState,
    ) {
        val compact = chrome.layout.is_compact_settings_panel(panel)
        val legacyPanel = chrome.layout.legacy_traffic_panel_bounds(panel, state)
        val viewport = state.reference_panel_plan.contentViewport.to_pixel_rect(
            panel,
            state.pixels_per_dp,
        )
        canvas.withSave {
            clipRect(viewport)
            draw_filter_search_control(this, legacyPanel, style, state)
            if (compact) {
                draw_compact_filters_panel_contents(this, legacyPanel, state)
            } else {
                draw_portrait_filters_panel_contents(this, legacyPanel, state)
            }
            text_paint.textAlign = Paint.Align.LEFT
            text_paint.isFakeBoldText = false
            text_paint.textSize = sp(if (compact) 10 else 11)
            text_paint.color = style.visual_theme.colors.muted
            val statsBounds = if (compact) {
                chrome.layout.compact_settings_left_column(legacyPanel)
            } else {
                RectF(
                    legacyPanel.left + dp(18),
                    legacyPanel.bottom - dp(38),
                    legacyPanel.right - dp(18),
                    legacyPanel.bottom,
                )
            }
            val statsY = if (compact) {
                chrome.layout.filter_reset_button_bounds(legacyPanel).centerY() + dp(4)
            } else {
                legacyPanel.bottom - dp(22)
            }
            draw_fitted_left_text(
                this,
                state.stats_summary,
                statsBounds.left,
                statsY,
                statsBounds.width(),
                text_paint.textSize,
                sp(8),
            )
        }
    }

    private fun draw_reference_map_filters(
        canvas: Canvas,
        panel: RectF,
        style: FlightMapPanelStyle,
        state: FiltersPanelState,
    ) {
        val plan = state.reference_panel_plan
        val viewport = plan.contentViewport.to_pixel_rect(panel, state.pixels_per_dp)
        canvas.withSave {
            clipRect(viewport)
            plan.sections.forEach { section ->
                section.heading?.let { heading ->
                    draw_reference_text_plan(
                        this,
                        panel,
                        heading,
                        style,
                        style.visual_theme.colors.text,
                    )
                }
            }
            plan.controls.filter { it.kind == ReferenceControlKind.SWITCH }.forEach { control ->
                draw_reference_switch(this, panel, style, state, control)
            }
            plan.statusMessage?.let { status ->
                draw_reference_text_plan(
                    this,
                    panel,
                    status,
                    style,
                    style.visual_theme.colors.muted,
                )
            }
        }
    }

    private fun draw_reference_switch(
        canvas: Canvas,
        panel: RectF,
        style: FlightMapPanelStyle,
        state: FiltersPanelState,
        control: ReferenceControlPlan,
    ) {
        val colors = style.visual_theme.colors
        val focused = control.actionId == state.reference_focused_action_id
        val selected = control.onOff == true
        val masterEnabled = control.sectionMasterEnabled != false
        chrome.draw_control_surface(
            canvas,
            control.bounds.to_pixel_rect(panel, state.pixels_per_dp),
            colors.button_fill,
            if (selected || focused) colors.accent_blue else colors.button_stroke,
            selected || focused,
        )
        draw_reference_swatch(
            canvas,
            panel,
            control,
            state.pixels_per_dp,
            masterEnabled,
            style,
        )
        val labelColor = if (masterEnabled) colors.text else colors.muted
        control.labelText?.let { label ->
            draw_reference_text_plan(canvas, panel, label, style, labelColor)
        }
        control.stateText?.let { status ->
            draw_reference_text_plan(
                canvas,
                panel,
                status,
                style,
                if (selected) colors.accent_green else colors.muted,
            )
        }
    }

    private fun draw_reference_swatch(
        canvas: Canvas,
        panel: RectF,
        control: ReferenceControlPlan,
        density: Float,
        masterEnabled: Boolean,
        style: FlightMapPanelStyle,
    ) {
        val bounds = control.swatchBounds?.to_pixel_rect(panel, density) ?: return
        val alpha = if (masterEnabled) 255 else 150
        when (val swatch = control.swatch) {
            is ReferenceLabelStyleSwatch -> {
                val previousTypeface = text_paint.typeface
                val previousLetterSpacing = text_paint.letterSpacing
                val previousStyle = text_paint.style
                val previousAlign = text_paint.textAlign
                val previousTextSize = text_paint.textSize
                val previousStrokeWidth = text_paint.strokeWidth
                val previousColor = text_paint.color
                val previousFakeBold = text_paint.isFakeBoldText
                text_paint.textAlign = Paint.Align.CENTER
                text_paint.textSize = dp(12)
                text_paint.isFakeBoldText = false
                val referenceTypeface = Typeface.create(
                    style.visual_theme.style.font_family,
                    Typeface.NORMAL,
                )
                text_paint.typeface = Typeface.create(
                    referenceTypeface,
                    swatch.fontWeight,
                    swatch.italic,
                )
                text_paint.letterSpacing = swatch.letterSpacingEm
                val metrics = text_paint.fontMetrics
                val baseline = bounds.centerY() - (metrics.ascent + metrics.descent) / 2f
                text_paint.style = Paint.Style.STROKE
                text_paint.strokeWidth = dp(2f)
                text_paint.color = with_alpha(swatch.haloArgb, alpha)
                canvas.drawText("Aa", bounds.centerX(), baseline, text_paint)
                text_paint.style = Paint.Style.FILL
                text_paint.color = with_alpha(swatch.colorArgb, alpha)
                canvas.drawText("Aa", bounds.centerX(), baseline, text_paint)
                text_paint.typeface = previousTypeface
                text_paint.letterSpacing = previousLetterSpacing
                text_paint.style = previousStyle
                text_paint.textAlign = previousAlign
                text_paint.textSize = previousTextSize
                text_paint.strokeWidth = previousStrokeWidth
                text_paint.color = previousColor
                text_paint.isFakeBoldText = previousFakeBold
            }
            is ReferenceOutlineStyleSwatch -> {
                val previousStyle = stroke_paint.style
                val previousStrokeCap = stroke_paint.strokeCap
                val previousPathEffect = stroke_paint.pathEffect
                val previousStrokeWidth = stroke_paint.strokeWidth
                val previousColor = stroke_paint.color
                val centerY = bounds.centerY()
                stroke_paint.style = Paint.Style.STROKE
                stroke_paint.strokeCap = Paint.Cap.ROUND
                stroke_paint.pathEffect = reference_swatch_path_effect(swatch.pattern)
                stroke_paint.strokeWidth = dp(swatch.lineWidthDp + 2f)
                stroke_paint.color = with_alpha(swatch.haloArgb, alpha)
                canvas.drawLine(bounds.left, centerY, bounds.right, centerY, stroke_paint)
                stroke_paint.strokeWidth = dp(swatch.lineWidthDp)
                stroke_paint.color = with_alpha(swatch.colorArgb, alpha)
                canvas.drawLine(bounds.left, centerY, bounds.right, centerY, stroke_paint)
                stroke_paint.style = previousStyle
                stroke_paint.strokeCap = previousStrokeCap
                stroke_paint.pathEffect = previousPathEffect
                stroke_paint.strokeWidth = previousStrokeWidth
                stroke_paint.color = previousColor
            }
            null -> Unit
        }
    }

    private fun reference_swatch_path_effect(pattern: ReferenceOutlinePattern): DashPathEffect? =
        when (pattern) {
            ReferenceOutlinePattern.SOLID -> null
            ReferenceOutlinePattern.LONG_DASH -> DashPathEffect(floatArrayOf(dp(10), dp(5)), 0f)
            ReferenceOutlinePattern.SHORT_DASH -> DashPathEffect(floatArrayOf(dp(5), dp(4)), 0f)
            ReferenceOutlinePattern.DASH_DOT -> DashPathEffect(
                floatArrayOf(dp(8), dp(3), dp(2), dp(3)),
                0f,
            )
            ReferenceOutlinePattern.DOT -> DashPathEffect(floatArrayOf(dp(2), dp(3)), 0f)
        }

    private fun draw_reference_text_plan(
        canvas: Canvas,
        panel: RectF,
        plan: ReferenceTextPlan,
        style: FlightMapPanelStyle,
        color: Int,
        centerHorizontally: Boolean = false,
    ) {
        val bounds = plan.bounds.to_pixel_rect(panel, chrome.dp(1f))
        val previousTypeface = text_paint.typeface
        val previousStyle = text_paint.style
        val previousAlign = text_paint.textAlign
        val previousTextSize = text_paint.textSize
        val previousColor = text_paint.color
        val previousFakeBold = text_paint.isFakeBoldText
        val previousLetterSpacing = text_paint.letterSpacing
        text_paint.style = Paint.Style.FILL
        text_paint.textAlign = if (centerHorizontally) Paint.Align.CENTER else Paint.Align.LEFT
        text_paint.textSize = sp(plan.textSizeSp)
        text_paint.isFakeBoldText = false
        text_paint.letterSpacing = 0f
        val referenceTypeface = Typeface.create(
            style.visual_theme.style.font_family,
            Typeface.NORMAL,
        )
        text_paint.typeface = Typeface.create(
            referenceTypeface,
            plan.fontWeight,
            plan.italic,
        )
        text_paint.color = color
        val lineHeight = bounds.height() / plan.lines.size.coerceAtLeast(1)
        val metrics = text_paint.fontMetrics
        plan.lines.forEachIndexed { index, line ->
            val lineCenter = bounds.top + lineHeight * (index + 0.5f)
            val baseline = lineCenter - (metrics.ascent + metrics.descent) / 2f
            canvas.drawText(
                line,
                if (centerHorizontally) bounds.centerX() else bounds.left,
                baseline,
                text_paint,
            )
        }
        text_paint.typeface = previousTypeface
        text_paint.style = previousStyle
        text_paint.textAlign = previousAlign
        text_paint.textSize = previousTextSize
        text_paint.color = previousColor
        text_paint.isFakeBoldText = previousFakeBold
        text_paint.letterSpacing = previousLetterSpacing
    }

    // Draw alert-volume controls and the current priority queue without inventing aircraft status.
    fun draw_priority_tracker_panel(
        canvas: Canvas,
        w: Float,
        h: Float,
        style: FlightMapPanelStyle,
        state: PriorityTrackerPanelState
    ) {
        paint.style = Paint.Style.FILL
        val rect = chrome.layout.priority_tracker_panel_bounds(w, h)
        chrome.draw_panel_surface(
            canvas,
            rect,
            style.visual_theme.colors.panel_alt,
            style.visual_theme.style.modal_panel_alpha
        )

        draw_panel_title(canvas, rect, "Notification Range", style)
        chrome.draw_choice_button(
            canvas,
            chrome.layout.priority_close_button_bounds(rect),
            "Close",
            false
        )

        if (chrome.layout.is_compact_settings_panel(rect)) {
            draw_compact_priority_tracker_contents(canvas, rect, style, state)
            return
        }

        chrome.draw_choice_button(
            canvas,
            chrome.layout.priority_tracking_toggle_bounds(rect),
            if (state.priority_tracking_enabled) "Queue on" else "Queue off",
            state.priority_tracking_enabled
        )
        chrome.draw_choice_button(
            canvas,
            chrome.layout.priority_ring_toggle_bounds(rect),
            if (state.priority_range_circle_visible) "Alert ring on" else "Alert ring off",
            state.priority_range_circle_visible
        )

        text_paint.textAlign = Paint.Align.LEFT
        text_paint.isFakeBoldText = false
        text_paint.textSize = sp(12)
        text_paint.color = style.visual_theme.colors.muted
        canvas.drawText("Notification range", rect.left + dp(18), rect.top + dp(136), text_paint)
        draw_adjuster_row(
            canvas,
            rect,
            rect.top + dp(162),
            "Horizontal",
            state.alert_distance_label,
            chrome.layout.alert_distance_minus_bounds(rect),
            chrome.layout.alert_distance_plus_bounds(rect),
            style,
            state.long_press_fill,
            PriorityRangeAdjustButton.DISTANCE_MINUS,
            PriorityRangeAdjustButton.DISTANCE_PLUS
        )
        draw_adjuster_row(
            canvas,
            rect,
            rect.top + dp(250),
            "Vertical",
            state.alert_altitude_label,
            chrome.layout.alert_altitude_minus_bounds(rect),
            chrome.layout.alert_altitude_plus_bounds(rect),
            style,
            state.long_press_fill,
            PriorityRangeAdjustButton.ALTITUDE_MINUS,
            PriorityRangeAdjustButton.ALTITUDE_PLUS
        )

        text_paint.textAlign = Paint.Align.LEFT
        text_paint.isFakeBoldText = false
        text_paint.textSize = sp(12)
        text_paint.color = style.visual_theme.colors.muted
        canvas.drawText("Aircraft in queue", rect.left + dp(18), rect.top + dp(344), text_paint)

        if (state.aircraft_rows.isEmpty()) {
            text_paint.isFakeBoldText = true
            text_paint.textSize = sp(17)
            text_paint.color = style.visual_theme.colors.text
            draw_fitted_left_text(
                canvas,
                if (state.priority_tracking_enabled) "No aircraft in queue" else "Queue is off",
                rect.left + dp(18),
                rect.top + dp(386),
                rect.width() - dp(36),
                sp(17),
                sp(10)
            )
            text_paint.isFakeBoldText = false
            return
        }

        val row_start_y = rect.top + dp(382)
        val visible_rows = ((rect.bottom - dp(44) - row_start_y) / dp(64)).toInt()
            .coerceIn(1, PRIORITY_PANEL_ROWS)
        var y = row_start_y
        state.aircraft_rows.take(visible_rows).forEach { item ->
            y = draw_priority_aircraft_row(canvas, rect, y, item, style)
        }
        if (state.aircraft_rows.size > visible_rows) {
            text_paint.textAlign = Paint.Align.LEFT
            text_paint.isFakeBoldText = false
            text_paint.textSize = sp(11)
            text_paint.color = style.visual_theme.colors.muted
            draw_fitted_left_text(
                canvas,
                "+${state.aircraft_rows.size - visible_rows} more",
                rect.left + dp(18),
                y + dp(8),
                rect.width() - dp(36),
                sp(11),
                sp(8)
            )
        }
    }

    private fun map_labels_button_label(state: SettingsPanelState, compact: Boolean): String {
        val prefix = if (compact) "Labels" else "Map labels"
        return when {
            state.map_labels_enabled && state.map_borders_enabled -> "$prefix on"
            state.map_labels_enabled || state.map_borders_enabled -> "$prefix mixed"
            else -> "$prefix off"
        }
    }

    private fun draw_watcher_notification_status(
        canvas: Canvas,
        rect: RectF,
        state: SettingsPanelState,
        style: FlightMapPanelStyle
    ) {
        val status = state.watcher_notification_hider_status
        val fill = when (status) {
            MonitoringNotificationHiderStatus.UP -> style.visual_theme.colors.accent_green
            MonitoringNotificationHiderStatus.BOOTING -> style.visual_theme.colors.accent_orange
            MonitoringNotificationHiderStatus.DOWN -> style.visual_theme.colors.danger
        }
        val label = when (status) {
            MonitoringNotificationHiderStatus.UP -> "Notification watcher: UP"
            MonitoringNotificationHiderStatus.BOOTING -> "Notification watcher: BOOTING"
            MonitoringNotificationHiderStatus.DOWN -> "Notification watcher: DOWN"
        }
        val radius = chrome.control_radius().coerceAtLeast(dp(4))
        paint.style = Paint.Style.FILL
        paint.color = with_alpha(fill, 220)
        canvas.drawRoundRect(rect, radius, radius, paint)

        stroke_paint.style = Paint.Style.STROKE
        stroke_paint.strokeWidth = dp(1.2f)
        stroke_paint.color = with_alpha(Color.WHITE, 150)
        canvas.drawRoundRect(rect, radius, radius, stroke_paint)

        text_paint.textAlign = Paint.Align.CENTER
        text_paint.isFakeBoldText = true
        text_paint.color = if (status == MonitoringNotificationHiderStatus.BOOTING) {
            Color.rgb(28, 20, 8)
        } else {
            Color.WHITE
        }
        draw_fitted_center_text(
            canvas,
            label,
            rect.left + dp(8),
            rect.right - dp(8),
            rect.centerY() + dp(5),
            sp(12),
            sp(8)
        )
        if (status == MonitoringNotificationHiderStatus.BOOTING) {
            chrome.request_animation_frame()
        }
    }

    private fun draw_map_label_text_slider(
        canvas: Canvas,
        rect: RectF,
        state: MapLabelsPanelState,
        style: FlightMapPanelStyle
    ) {
        val colors = style.visual_theme.colors
        val progress = ((state.label_text_scale - MAP_LABEL_TEXT_SCALE_MIN) /
                (MAP_LABEL_TEXT_SCALE_MAX - MAP_LABEL_TEXT_SCALE_MIN)).coerceIn(0f, 1f)
        text_paint.textAlign = Paint.Align.LEFT
        text_paint.isFakeBoldText = false
        text_paint.textSize = sp(11)
        text_paint.color = colors.muted
        canvas.drawText("Map text size", rect.left, rect.top + dp(12), text_paint)
        text_paint.textAlign = Paint.Align.RIGHT
        text_paint.isFakeBoldText = true
        text_paint.color = colors.text
        canvas.drawText(
            String.format(Locale.US, "%.2fx", state.label_text_scale),
            rect.right,
            rect.top + dp(12),
            text_paint
        )

        val track_left = rect.left
        val track_right = rect.right
        val track_y = rect.bottom - dp(14)
        val track_height = dp(5)
        val track = RectF(track_left, track_y - track_height / 2f, track_right, track_y + track_height / 2f)
        paint.style = Paint.Style.FILL
        paint.color = with_alpha(colors.muted, 72)
        canvas.drawRoundRect(track, track_height, track_height, paint)
        val fill = RectF(track.left, track.top, track.left + track.width() * progress, track.bottom)
        paint.color = colors.accent_green
        canvas.drawRoundRect(fill, track_height, track_height, paint)
        paint.color = colors.text
        canvas.drawCircle(track.left + track.width() * progress, track_y, dp(8), paint)
    }

    private fun draw_disabled_choice_button(
        canvas: Canvas,
        rect: RectF,
        label: String,
        style: FlightMapPanelStyle
    ) {
        val colors = style.visual_theme.colors
        chrome.draw_control_surface(
            canvas,
            rect,
            with_alpha(colors.button_fill, 54),
            with_alpha(colors.muted, 112),
            false
        )
        val previous_align = text_paint.textAlign
        text_paint.textAlign = Paint.Align.CENTER
        text_paint.isFakeBoldText = false
        text_paint.textSize = sp(12)
        val available_width = (rect.width() - dp(12)).coerceAtLeast(dp(4))
        while (text_paint.textSize > sp(8) && text_paint.measureText(label) > available_width) {
            text_paint.textSize -= dp(0.5f)
        }
        val display = if (text_paint.measureText(label) <= available_width) {
            label
        } else {
            chrome.ellipsize(label, available_width)
        }
        text_paint.color = with_alpha(colors.muted, 170)
        val metrics = text_paint.fontMetrics
        canvas.drawText(
            display,
            rect.centerX(),
            rect.centerY() - (metrics.ascent + metrics.descent) / 2f,
            text_paint
        )
        text_paint.textAlign = previous_align
    }

    private fun draw_settings_section_label(
        canvas: Canvas,
        x: Float,
        y: Float,
        label: String,
        style: FlightMapPanelStyle
    ) {
        text_paint.textAlign = Paint.Align.LEFT
        text_paint.isFakeBoldText = false
        text_paint.textSize = sp(12)
        text_paint.color = style.visual_theme.colors.muted
        canvas.drawText(label, x, y, text_paint)
    }

    // Layer buttons include source state suffixes so unavailable or empty real layers are labeled honestly.
    private fun draw_layer_toggle_button(
        canvas: Canvas,
        rect: RectF,
        label: String,
        enabled: Boolean,
        kind: AviationLayerKind,
        state: AviationLayersPanelState
    ) {
        val status = state.snapshot?.statuses?.get(kind)
        val suffix = when {
            !enabled -> "off"
            status?.state == AviationLayerState.LOADED -> "on"
            status?.state == AviationLayerState.PARTIAL ->
                if (status.showing_last_good) "stale" else "partial"
            status?.state == AviationLayerState.EMPTY -> "empty"
            status?.state == AviationLayerState.UNAVAILABLE && status.showing_last_good -> "stale"
            status?.state == AviationLayerState.UNAVAILABLE -> "retry"
            state.fetch_in_flight -> "loading"
            else -> "on"
        }
        chrome.draw_choice_button(canvas, rect, "$label $suffix", enabled)
    }

    private fun impact_methodology_items(): List<Pair<String, String>> {
        return listOf(
            "Trace first" to "Only real trace points from the aircraft source are used. App-session dots are never stored as a path.",
            "Aircraft profile" to "Live web/feed type is tried first, then registry/API metadata. Known ICAO types use a type benchmark; otherwise class benchmarks are used.",
            "Phase model" to "Observed legs are split into ground, climb, cruise, descent, low-level, or time-only using trace altitude, speed, and timestamps.",
            "Carbon math" to "CO2 range = profile gal/hr x phase multiplier x trace hours x EIA kg CO2/gal. Jet fuel uses 9.75; avgas uses 8.31.",
            "Score" to "0-100 is log-scaled kg CO2/hr. When a phase trace exists it scores observed intensity; otherwise it scores the profile rate.",
            "Full flight" to "Shown only when real origin, destination, and trace progress are credible enough to route-scale the observed estimate.",
            "Not claimed" to "No exact fuel flow, payload, passenger count, SAF blend, contrails, NOx, noise, or per-passenger allocation is inferred."
        )
    }

    private fun draw_methodology_column(
        canvas: Canvas,
        rect: RectF,
        items: List<Pair<String, String>>,
        style: FlightMapPanelStyle
    ) {
        var y = rect.top
        items.forEach { item ->
            y = draw_methodology_item(
                canvas,
                rect,
                y,
                item.first,
                item.second,
                max_lines = 2,
                style
            )
        }
    }

    private fun draw_methodology_item(
        canvas: Canvas,
        rect: RectF,
        y: Float,
        label: String,
        body: String,
        max_lines: Int,
        style: FlightMapPanelStyle
    ): Float {
        text_paint.textAlign = Paint.Align.LEFT
        text_paint.isFakeBoldText = true
        text_paint.textSize = sp(11)
        text_paint.color = style.visual_theme.colors.text
        canvas.drawText(label, rect.left, y, text_paint)

        text_paint.isFakeBoldText = false
        text_paint.textSize = sp(11)
        text_paint.color = style.visual_theme.colors.muted
        val bottom =
            chrome.draw_wrapped_text(canvas, body, rect.left, y + dp(18), rect.width(), max_lines)
        return bottom + dp(12)
    }

    // Search control owns the caret animation while FlightMapView owns actual text input.
    private fun draw_filter_search_control(
        canvas: Canvas,
        panel: RectF,
        style: FlightMapPanelStyle,
        state: FiltersPanelState
    ) {
        val colors = style.visual_theme.colors
        val theme_style = style.visual_theme.style
        val search = chrome.layout.filter_search_box_bounds(panel)
        val stroke = if (state.filter_search_focused) colors.accent_green else colors.button_stroke
        val fill =
            if (theme_style.treatment == ThemeTreatment.PLAIN) colors.button_fill else with_alpha(
                colors.button_fill,
                theme_style.control_alpha
            )
        chrome.draw_control_surface(canvas, search, fill, stroke, state.filter_search_focused)

        val display = state.filter_search_query.ifBlank { "Callsign, reg, ICAO hex" }
        text_paint.textAlign = Paint.Align.LEFT
        text_paint.isFakeBoldText = state.filter_search_query.isNotBlank()
        text_paint.textSize = sp(13)
        text_paint.color = if (state.filter_search_query.isBlank()) colors.muted else colors.text
        val max_width = search.width() - dp(24)
        canvas.drawText(
            chrome.ellipsize(display, max_width),
            search.left + dp(12),
            search.centerY() + dp(5),
            text_paint
        )
        if (state.filter_search_focused && SystemClock.elapsedRealtime() % 1000L < 560L) {
            val visible_text = if (state.filter_search_query.isBlank()) "" else chrome.ellipsize(
                state.filter_search_query,
                max_width
            )
            val caret_x =
                (search.left + dp(12) + text_paint.measureText(visible_text)).coerceAtMost(
                    search.right - dp(12)
                )
            stroke_paint.color = colors.accent_green
            stroke_paint.strokeWidth = dp(1.2f)
            canvas.drawLine(
                caret_x,
                search.top + dp(9),
                caret_x,
                search.bottom - dp(9),
                stroke_paint
            )
            chrome.request_animation_frame()
        }
        text_paint.isFakeBoldText = false

        chrome.draw_choice_button(
            canvas,
            chrome.layout.filter_search_find_button_bounds(panel),
            "Find live",
            false
        )
        chrome.draw_choice_button(
            canvas,
            chrome.layout.filter_search_clear_button_bounds(panel),
            "Clear",
            false
        )
    }

